{"content":""""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import time

from app.config import CACHE_PATH, CACHE_TTL


def _load_entries():
    try:
        with open(CACHE_PATH, encoding='utf-8') as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


def get_or_load(key, loader, now=None):
    now = time.time() if now is None else now
    entries = _load_entries()
    entry = entries.get(key)
    if entry is not None and now - entry.get('stored_at', 0) < CACHE_TTL:
        return entry['value']
    value = loader()
    entries[key] = {'stored_at': now, 'value': value}
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, 'w', encoding='utf-8') as fh:
        json.dump(entries, fh)
    return value
